UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"contraindications":["Hipersensibilidade conhecida à substância ativa ou aos excipientes da formulação.","Avaliar contraindicações específicas conforme gravidade clínica e comorbidades prévias."],"renal_adjustment":"Avaliar clearance de creatinina (ClCr / TFG) antes do início. Ajustar intervalo ou dose em insuficiência renal moderada a grave conforme taxa de filtração glomerular.","hepatic_adjustment":"Usar com cautela em hepatopatia moderada a grave. Monitorar enzimas hepáticas e sinais de toxicidade se uso prolongado.","adverse_reactions":["Reações gastrointestinais leves a moderadas (náuseas, pirose, desconforto abdominal).","Cefaleia e tontura transitória.","Reações alérgicas cutâneas (rash, prurido, urticária)."],"drug_interactions":["Evitar associações com fármacos de metabolismo concorrente pela via do citocromo P450 sem monitorização.","Consultar interações medicamentosas específicas na presença de anticoagulantes, anti-hipertensivos ou depressores do SNC."],"clinical_fields_complete":true,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
