UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"contraindications":["Úlcera péptica ativa ou histórico de hemorragia gastrointestinal recorrente.","Insuficiência cardíaca grave (NYHA IV), insuficiência renal grave (ClCr < 30 mL/min) ou hepática grave.","Terceiro trimestre da gestação (risco de fechamento precoce do ducto arterioso fetal)."],"renal_adjustment":"Evitar em ClCr < 30 mL/min; em insuficiência leve a moderada, usar menor dose eficaz pelo menor tempo possível e monitorar creatinina e volemia.","hepatic_adjustment":"Cautela em hepatopatias; evitar em cirrose descompensada pelo risco de insuficiência renal aguda secundária (síndrome hepatorrenal).","adverse_reactions":["Dispepsia, dor epigástrica, náuseas e risco de úlcera péptica / sangramento digestivo.","Retenção hidrossalina, piora da hipertensão arterial e edema periférico.","Nefrotoxicidade funcional por inibição de prostaglandinas vasodilatadoras renais."],"drug_interactions":["Anticoagulantes e antiplaquetários: aumento expressivo do risco de sangramento gastrointestinal.","IECA, BRA e diuréticos: redução da eficácia anti-hipertensiva e risco sinérgico de lesão renal aguda (''triplo golpe'').","Lítio e metotrexato: elevação dos níveis séricos com risco de toxicidade grave."],"clinical_fields_complete":true,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 4640;
