UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"contraindications":["Anormalidades do esôfago que retardem o esvaziamento esofágico (estenose, acalasia).","Incapacidade de permanecer em pé ou sentado por pelo menos 30 a 60 minutos.","Hipocalcemia não corrigida.","Insuficiência renal grave (ClCr < 35 mL/min)."],"renal_adjustment":"Não recomendado se ClCr < 35 mL/min devido à falta de evidências de segurança e eliminação renal predominante.","hepatic_adjustment":"Sem necessidade de ajuste de dose (não sofre metabolização hepática).","adverse_reactions":["Esofagite erosiva, úlceras esofágicas, disfagia e dor retroesternal.","Dores musculoesqueléticas ósseas difusas.","Raramente: osteonecrose de mandíbula e fratura atípica de fêmur em uso muito prolongado."],"drug_interactions":["Cálcio, antiácidos, suplementos de ferro e alimentos: reduzem drasticamente a absorção; tomar em jejum completo apenas com água pura e aguardar 30 a 60 minutos antes de ingerir outros itens."],"clinical_fields_complete":true,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
