UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"contraindications":["Tuberculose ativa ou outras infecções graves ativas (sepse, infecções fúngicas oportunistas).","Insuficiência cardíaca moderada a grave (NYHA III/IV).","Hipersensibilidade ao princípio ativo ou proteínas murinas/humanas."],"renal_adjustment":"Não há recomendação formal de ajuste de dose por ser eliminado por depuração proteica reticuloendotelial.","hepatic_adjustment":"Sem necessidade de ajuste específico; monitorar enzimas hepáticas e sorologias para hepatite B (risco de reativação viral).","adverse_reactions":["Reações no local da injeção (eritema, dor, prurido, edema).","Risco aumentado de infecções graves e oportunistas (tuberculose, reativação de herpes zoster).","Raramente: desmielinização do SNC e reações autoimunes tipo lúpus induzido."],"drug_interactions":["Vacinas de vírus vivos atenuados: terminantemente contraindicadas durante o tratamento.","Outros imunobiológicos (ex.: anakinra, abatacepte): não associar pelo risco excessivo de infecções graves."],"clinical_fields_complete":true,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
