UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"contraindications":["Insuficiência renal grave (TFG < 30 mL/min/1,73m²).","Acidose metabólica aguda ou crônica (incluindo cetoacidose diabética).","Condições agudas com potencial de alteração da função renal (desidratação grave, choque, sepse)."],"renal_adjustment":"TFG 45–59 mL/min: dose máxima 1000 mg/dia; monitorar função renal a cada 3–6 meses. TFG 30–44 mL/min: dose máxima 500–1000 mg/dia. TFG < 30 mL/min: contraindicado.","hepatic_adjustment":"Contraindicado em insuficiência hepática grave devido ao risco aumentado de acidose láctica.","adverse_reactions":["Gastrointestinais: diarreia, náuseas, vômitos, flatulência e dor abdominal (frequentes, reduzem com tomada junto às refeições).","Deficiência de vitamina B12 em uso prolongado.","Acidose láctica (rara, mas potencialmente fatal)."],"drug_interactions":["Contrastes iodados: suspender metformina antes ou no momento do procedimento em pacientes com TFG < 60 mL/min; reiniciar 48h após se função renal estável.","Álcool: potencializa o risco de acidose láctica."],"clinical_fields_complete":true,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
